from pathlib import Path

ROOT = Path('docs')

FORM_HTML = """
    <section id=\"claim-form\" class=\"px-6 pb-20\">\n        <div class=\"mx-auto max-w-7xl rounded-[36px] border border-slate-200 bg-white p-6 shadow-xl md:p-8\">\n            <div class=\"grid gap-8 lg:grid-cols-[0.95fr_1.05fr]\">\n                <div>\n                    <div class=\"text-sm font-bold uppercase tracking-[0.2em] text-slate-500\">Claim, edit, or remove</div>\n                    <h2 class=\"mt-3 text-3xl font-black text-slate-900 md:text-4xl\">Business owner request form</h2>\n                    <p class=\"mt-4 text-lg leading-8 text-slate-600\">Use this form to request ownership, ask for content edits, or request removal. The same submission path used by the consent flow sends the details to the website owner inbox.</p>\n                    <ul class=\"mt-5 list-disc space-y-2 pl-6 text-slate-600\">\n                        <li>Choose whether you want to claim the preview as-is, claim it with edits, or request removal.</li>\n                        <li>Tell us your preferred contact method so we can follow up quickly.</li>\n                        <li>The form is responsive and works on phone, tablet, and desktop.</li>\n                    </ul>\n                </div>\n                <form id=\"claimRequestForm\" class=\"rounded-[28px] border border-slate-200 bg-slate-50 p-5 shadow-sm md:p-6\">\n                    <div class=\"grid gap-4 md:grid-cols-2\">\n                        <label class=\"text-sm font-semibold text-slate-700\">\n                            Business name\n                            <input id=\"claimBusinessName\" name=\"business\" type=\"text\" required class=\"mt-2 w-full rounded-2xl border border-slate-300 bg-white px-4 py-3 text-slate-900 outline-none ring-0 transition focus:border-slate-400\" />\n                        </label>\n                        <label class=\"text-sm font-semibold text-slate-700\">\n                            Owner / representative name\n                            <input id=\"claimOwnerName\" name=\"name\" type=\"text\" required class=\"mt-2 w-full rounded-2xl border border-slate-300 bg-white px-4 py-3 text-slate-900 outline-none ring-0 transition focus:border-slate-400\" />\n                        </label>\n                        <label class=\"text-sm font-semibold text-slate-700\">\n                            Phone number\n                            <input id=\"claimPhone\" name=\"phone\" type=\"tel\" required class=\"mt-2 w-full rounded-2xl border border-slate-300 bg-white px-4 py-3 text-slate-900 outline-none ring-0 transition focus:border-slate-400\" />\n                        </label>\n                        <label class=\"text-sm font-semibold text-slate-700\">\n                            Email address\n                            <input id=\"claimEmail\" name=\"email\" type=\"email\" required class=\"mt-2 w-full rounded-2xl border border-slate-300 bg-white px-4 py-3 text-slate-900 outline-none ring-0 transition focus:border-slate-400\" />\n                        </label>\n                    </div>\n\n                    <label class=\"mt-4 block text-sm font-semibold text-slate-700\">\n                        Request type\n                        <select id=\"claimType\" name=\"request_type\" class=\"mt-2 w-full rounded-2xl border border-slate-300 bg-white px-4 py-3 text-slate-900 outline-none ring-0 transition focus:border-slate-400\">\n                            <option value=\"Claim as-is\">Claim as-is</option>\n                            <option value=\"Claim with edit\">Claim with edit</option>\n                            <option value=\"Not interested — request removal\">Not interested — request removal</option>\n                        </select>\n                    </label>\n\n                    <label id=\"claimNotesWrap\" class=\"mt-4 hidden text-sm font-semibold text-slate-700\">\n                        What should be added or changed?\n                        <textarea id=\"claimNotes\" name=\"notes\" rows=\"4\" class=\"mt-2 w-full rounded-2xl border border-slate-300 bg-white px-4 py-3 text-slate-900 outline-none ring-0 transition focus:border-slate-400\" placeholder=\"Tell us what should be updated, corrected, or added to the preview.\"></textarea>\n                    </label>\n\n                    <label class=\"mt-4 block text-sm font-semibold text-slate-700\">\n                        Preferred contact method\n                        <select id=\"claimContactMethod\" name=\"preferred_contact\" class=\"mt-2 w-full rounded-2xl border border-slate-300 bg-white px-4 py-3 text-slate-900 outline-none ring-0 transition focus:border-slate-400\">\n                            <option value=\"Email\">Email</option>\n                            <option value=\"Phone\">Phone</option>\n                            <option value=\"Either\">Either</option>\n                        </select>\n                    </label>\n\n                    <div class=\"mt-5 flex flex-col gap-3 sm:flex-row sm:items-center\">\n                        <button type=\"submit\" class=\"inline-flex items-center justify-center rounded-full bg-slate-900 px-6 py-3 text-sm font-bold text-white shadow-sm transition hover:bg-slate-700\">Send request</button>\n                        <p id=\"claimStatus\" class=\"text-sm text-slate-600\">We’ll send this request using the same consent submission path already used on the preview pages.</p>\n                    </div>\n                    <iframe name=\"claimFrame\" id=\"claimFrame\" class=\"hidden\"></iframe>\n                </form>\n            </div>\n        </div>\n    </section>\n\n    <script>\n    (function(){\n      var webhookEndpoint = 'https://script.google.com/macros/s/AKfycbzqGyfeKxwdmwM0B30PigVK9ULJUABx45MIwDfcQjlbOErbWkIrbTU5pTTacEpy6KEACg/exec';\n      var form = document.getElementById('claimRequestForm');\n      var typeSelect = document.getElementById('claimType');\n      var notesWrap = document.getElementById('claimNotesWrap');\n      var statusEl = document.getElementById('claimStatus');\n      var businessNameEl = document.getElementById('claimBusinessName');\n      var ownerNameEl = document.getElementById('claimOwnerName');\n      var phoneEl = document.getElementById('claimPhone');\n      var emailEl = document.getElementById('claimEmail');\n\n      function getBusinessName(){\n        return (document.querySelector('h1') && document.querySelector('h1').textContent.trim()) || (document.title || 'Business preview');\n      }\n\n      function updateNotesVisibility(){\n        notesWrap.classList.toggle('hidden', typeSelect.value !== 'Claim with edit');\n      }\n\n      if (businessNameEl) businessNameEl.value = getBusinessName();\n      updateNotesVisibility();\n      if (typeSelect) typeSelect.addEventListener('change', updateNotesVisibility);\n\n      function submitViaHiddenForm(payload) {\n        if (!webhookEndpoint) return false;\n        var hiddenForm = document.createElement('form');\n        hiddenForm.method = 'POST';\n        hiddenForm.action = webhookEndpoint;\n        hiddenForm.target = 'claimFrame';\n        hiddenForm.style.display = 'none';\n\n        Object.keys(payload).forEach(function(key){\n          var input = document.createElement('input');\n          input.type = 'hidden';\n          input.name = key;\n          input.value = payload[key] || '';\n          hiddenForm.appendChild(input);\n        });\n\n        document.body.appendChild(hiddenForm);\n        hiddenForm.submit();\n        return true;\n      }\n\n      if (form) {\n        form.addEventListener('submit', function(event){\n          event.preventDefault();\n          var payload = {\n            business: businessNameEl.value.trim(),\n            name: ownerNameEl.value.trim(),\n            phone: phoneEl.value.trim(),\n            email: emailEl.value.trim(),\n            request_type: typeSelect.value,\n            notes: document.getElementById('claimNotes').value.trim(),\n            preferred_contact: document.getElementById('claimContactMethod').value,\n            source: 'business owner request form',\n            preview_url: window.location.href,\n            submitted_at: new Date().toISOString(),\n            user_agent: navigator.userAgent\n          };\n\n          statusEl.textContent = 'Thanks — your request is being sent using the existing consent submission flow.';\n          try { submitViaHiddenForm(payload); } catch (e) {\n            statusEl.textContent = 'The request could not be submitted automatically. Please use the contact details on the page.';\n          }\n        });\n      }\n    })();\n    </script>\n"""

changed = []
for page_dir in sorted(ROOT.glob('*')):
    if not page_dir.is_dir():
        continue
    html_path = page_dir / 'index.html'
    if not html_path.exists():
        continue
    text = html_path.read_text(encoding='utf-8')
    original = text
    text = text.replace('href="tel:0404960871"', 'href="#claim-form"')
    if 'id="claim-form"' not in text:
        text = text.replace('</body>', FORM_HTML + '\n</body>', 1)
    if text != original:
        html_path.write_text(text, encoding='utf-8')
        changed.append(page_dir.name)

print('UPDATED_PAGES', len(changed))
for name in changed[:50]:
    print(name)
